<template><section class="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8"><p class="text-sm uppercase tracking-[.35em] text-amber-200">Delegate Packages</p><h1 class="mt-4 text-5xl font-black">Choose your IWBIF delegate experience.</h1><div v-if="pending" class="mt-10 grid gap-5 md:grid-cols-2"><div v-for="n in 2" :key="n" class="h-80 animate-pulse rounded-[2rem] bg-white/5"/></div><div v-else-if="error" class="mt-10 rounded-3xl border border-red-400/30 bg-red-950/30 p-6 text-red-100">{{ error.message }}</div><div v-else-if="!packages.length" class="mt-10 rounded-3xl border border-white/10 bg-white/5 p-6 text-slate-300">Delegate packages will be published soon.</div><div v-else class="mt-10 grid gap-5 md:grid-cols-2 lg:grid-cols-3"><article v-for="item in packages" :key="item.id" class="glass-card flex flex-col rounded-[2rem] p-7"><p class="text-sm text-amber-200">{{ item.code }}</p><h2 class="mt-3 text-2xl font-bold">{{ item.name }}</h2><p class="mt-4 text-4xl font-black">{{ money(item.amount,item.currency) }}</p><NuxtLink :to="`/register?package=${item.id}`" class="mt-7 rounded-full bg-amber-300 px-5 py-3 text-center font-semibold text-slate-950">Select package</NuxtLink></article></div></section></template>
<script setup lang="ts">import {useEvent} from '~/composables/useEvent'; useSeoMeta({title:'Delegate Packages | IWBIF 2026'}); const {getEvents,getEventDelegatePackages}=useEvent(); const {data:response,pending,error}=await useAsyncData('iwbif-packages',async()=>{const events=await getEvents(1,1);const event=events.data[0];if(!event)throw new Error('No IWBIF event is currently published.');return getEventDelegatePackages(event.id)});const packages=computed(()=>response.value?.data.filter(item=>item.is_active)??[]);const money=(amount:number,currency:string)=>new Intl.NumberFormat('en-US',{style:'currency',currency}).format(amount);</script>
